import com.nexabuilder.core.entity.EntityService;
import com.nexabuilder.core.entity.SchemaDdlService;
import com.nexabuilder.core.ui.NexaListDef;
import com.nexabuilder.core.ui.NexaListRepository;
import com.nexabuilder.core.ui.NexaUiService;
import com.nexabuilder.core.user.User;
import org.apache.poi.ss.usermodel.Sheet;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.test.context.support.WithMockUser;
