import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * End-to-end coverage for the three list export endpoints
 * ({@code /api/v1/lists/{listId}/export.csv|.xlsx|.pdf}) through the
 * real H2 schema, the real {@code ScreenPermissionService} and the real
 * POI / OpenPDF writers — no test doubles.
 *
 * <p>The important behavioural pin is the soft-delete case: the runtime
 * page {@code /app/list/<id>} already treats a list with
 * {@code deleted_at} set as "not found" (migration 027), and the export
 * URLs must reach the same verdict instead of leaking trash-can data.
 *
 * <p>Fixtures use a random 8-char suffix so they neither collide with
 * seeded sample data nor with other tests sharing the suite-wide H2.
 * No cleanup, matching the other integration tests.
 */
@SpringBootTest
@AutoConfigureMockMvc
@WithMockUser(username = "admin", roles = {"ADMIN"})
class ListExportIntegrationTest {

    private static final String BOM = "\uFEFF";
    private static final String[] FORMATS = {"csv", "xlsx", "pdf"};

    @Autowired private MockMvc mockMvc;
    @Autowired private ObjectMapper objectMapper;
    @Autowired private DynamicEntityRepository entityRepository;
    @Autowired private NexaListRepository listRepository;
    @Autowired private EntityService entityService;
    @Autowired private SchemaDdlService schemaDdlService;
    @Autowired private JdbcTemplate jdbc;

    private record Fixture(String entityId, String tableName, String listId, String rowId) {}

    private Fixture seed() throws Exception {
        // Default fixture: no page_size (so listData falls back to 100) and a
        // single row — the shape the original export assertions were written
        // against. Kept delegating so those expectations stay untouched.
        return seed(null, 1);
    }

    /**
     * @param pageSize value for {@code nexa_list.page_size} — {@code null} leaves
     *                 the column unset, which is what most seeded lists look like.
     * @param rowCount how many rows to insert into the fixture table; the first
     *                 one keeps the {@code r_<sfx>} id the CSV / XLSX assertions use.
     */
    private Fixture seed(Integer pageSize, int rowCount) throws Exception {
        String sfx = UUID.randomUUID().toString().replace("-", "").substring(0, 8);
        String entityId = "export_" + sfx;
        String tableName = "t_export_" + sfx;
        String listId = "list_export_" + sfx;

        List<Map<String, Object>> fields = List.of(
                Map.of("name", "name", "label", "Name", "type", "string")
        );
        DynamicEntity entity = DynamicEntity.builder()
                .entityId(entityId)
                .entityName("Export " + sfx)
                .tableName(tableName)
                .keyColumn("id")
                .description("export fixture")
                .fieldsJson(objectMapper.writeValueAsString(fields))
                .active(true)
                .system(false)
                .regDttm(LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMddHHmmss")))
                .build();
        entity = entityRepository.save(entity);
        schemaDdlService.ensureTable(entity);

        // One row with a Hangul value so the CSV / XLSX assertions also
        // prove the UTF-8 path end to end.
        Map<String, Object> row = new LinkedHashMap<>();
        String rowId = "r_" + sfx;
        row.put("id", rowId);
        row.put("name", "홍길동");
        entityService.insert(tableName, row);

        for (int i = 1; i < rowCount; i++) {
            Map<String, Object> extra = new LinkedHashMap<>();
            extra.put("id", "r_" + sfx + "_" + i);
            extra.put("name", "홍길동 " + i);
            entityService.insert(tableName, extra);
        }

        List<Map<String, Object>> cols = List.of(
                Map.of("field", "id", "label", "ID"),
                Map.of("field", "name", "label", "이름")
        );
        NexaListDef list = NexaListDef.builder()
                .listId(listId)
                .listName("Export " + sfx)
                .entityId(entityId)
                .columnsJson(objectMapper.writeValueAsString(cols))
                .pageSize(pageSize)
                .active(true)
                .build();
        listRepository.save(list);

        return new Fixture(entityId, tableName, listId, rowId);
    }

    private static User adminSessionUser() {
        User u = new User();
        u.setUserId("admin");
        u.setUserName("admin");
        u.setAdmin(true);
        u.setActive(true);
        u.setRoleId("ADMIN");
        return u;
    }

    private static String exportUrl(Fixture f, String format) {
        return "/api/v1/lists/" + f.listId() + "/export." + format;
    }

    @Test
    void csvExportHasBomHeaderAndRows() throws Exception {
        Fixture f = seed();

        MvcResult result = mockMvc.perform(get(exportUrl(f, "csv"))
                        .sessionAttr("nexabuilder.user", adminSessionUser()))
                .andExpect(status().isOk())
                .andExpect(content().contentType("text/csv;charset=UTF-8"))
                .andExpect(header().string("Content-Disposition",
                        allOf(
                                startsWith("attachment"),
                                containsString("filename*=UTF-8''"))))
                .andReturn();

        // Read as UTF-8 explicitly — the default charset would mangle the BOM.
        String body = result.getResponse().getContentAsString(StandardCharsets.UTF_8);
        assertThat(body).startsWith(BOM);

        // writeRow emits CRLF and quotes only when a cell contains , " CR LF —
        // none of our values do, so the lines are the raw labels / values.
        String[] lines = body.substring(BOM.length()).split("\r\n");
        assertThat(lines[0]).isEqualTo("ID,이름");
        assertThat(lines[1]).isEqualTo(f.rowId() + ",홍길동");
    }

    @Test
    void xlsxExportOpensWithPoi() throws Exception {
        Fixture f = seed();

        MvcResult result = mockMvc.perform(get(exportUrl(f, "xlsx"))
                        .sessionAttr("nexabuilder.user", adminSessionUser()))
                .andExpect(status().isOk())
                .andExpect(content().contentType(
                        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"))
                .andExpect(header().string("Content-Disposition",
                        allOf(
                                startsWith("attachment"),
                                containsString("filename*=UTF-8''"))))
                .andReturn();

        byte[] bytes = result.getResponse().getContentAsByteArray();
        try (XSSFWorkbook wb = new XSSFWorkbook(new ByteArrayInputStream(bytes))) {
            Sheet sheet = wb.getSheetAt(0);
            assertThat(sheet.getRow(0).getCell(0).getStringCellValue()).isEqualTo("ID");
            assertThat(sheet.getRow(0).getCell(1).getStringCellValue()).isEqualTo("이름");
            assertThat(sheet.getRow(1).getCell(0).getStringCellValue()).isEqualTo(f.rowId());
            assertThat(sheet.getRow(1).getCell(1).getStringCellValue()).isEqualTo("홍길동");
        }
    }

    @Test
    void pdfExportStartsWithPdfMagic() throws Exception {
        Fixture f = seed();

        MvcResult result = mockMvc.perform(get(exportUrl(f, "pdf"))
                        .sessionAttr("nexabuilder.user", adminSessionUser()))
                .andExpect(status().isOk())
                .andExpect(content().contentType("application/pdf"))
                .andExpect(header().string("Content-Disposition",
                        allOf(
                                startsWith("attachment"),
                                containsString("filename*=UTF-8''"))))
                .andReturn();

        // Only the magic number — Hangul glyphs depend on whether the CJK
        // font pack is on the classpath, so the body isn't inspected further.
        byte[] bytes = result.getResponse().getContentAsByteArray();
        assertThat(bytes.length).isGreaterThan(5);
        assertThat(new String(bytes, 0, 5, StandardCharsets.US_ASCII)).isEqualTo("%PDF-");
    }

    @Test
    void softDeletedListIsNotExportableInAnyFormat() throws Exception {
        Fixture f = seed();

        // Same shape /admin/trash writes (yyyyMMddHHmmss string).
        NexaListDef list = listRepository.findById(f.listId()).orElseThrow();
        list.setDeletedAt("20260919000000");
        listRepository.save(list);

        for (String format : FORMATS) {
            MvcResult result = mockMvc.perform(get(exportUrl(f, format))
                            .sessionAttr("nexabuilder.user", adminSessionUser()))
                    .andExpect(status().isBadRequest())
                    .andExpect(jsonPath("$.success", is(false)))
                    .andExpect(jsonPath("$.message", is("List not found: " + f.listId())))
                    .andReturn();

            // No file bytes may leak: the JSON error must be the whole body.
            String contentType = result.getResponse().getContentType();
            assertThat(contentType)
                    .as("content-type for ." + format)
                    .startsWith("application/json");
            assertThat(result.getResponse().getHeader("Content-Disposition"))
                    .as("Content-Disposition for ." + format)
                    .isNull();
        }
    }

    /**
     * The export URLs are the second reader of the list data feed's paging
     * parameters: {@code readQueryParams} forwards the whole query string to
     * {@code NexaUiService.listData}, so {@code ?_limit=…} is caller-controlled
     * on a plain GET with no CSRF token. The {@link NexaUiService#MAX_FEED_ROWS}
     * ceiling lives inside {@code listData}, which is the single point all three
     * exporters go through — asserted here on CSV because it is the cheapest of
     * the three to count rows in; the PDF exporter (which builds the whole table
     * in memory) shares the same call.
     */
    @Test
    void exportQueryStringLimitIsClampedToMaxFeedRows() throws Exception {
        Fixture f = seed();
        // seed() inserts one row; top the table up past the ceiling in one
        // statement (H2 SYSTEM_RANGE) rather than thousands of inserts.
        int extra = NexaUiService.MAX_FEED_ROWS + 25 - 1;
        jdbc.update("INSERT INTO " + f.tableName() + " (id, name)"
                + " SELECT 'bulk' || X, '홍길동 ' || X FROM SYSTEM_RANGE(1, " + extra + ")");

        MvcResult result = mockMvc.perform(get(exportUrl(f, "csv"))
                        .param("_limit", "100000000")
                        .sessionAttr("nexabuilder.user", adminSessionUser()))
                .andExpect(status().isOk())
                .andReturn();

        String body = result.getResponse().getContentAsString(StandardCharsets.UTF_8);
        String[] lines = body.substring(BOM.length()).split("\r\n");
        // 1 header row + at most MAX_FEED_ROWS data rows.
        assertThat(lines).hasSize(NexaUiService.MAX_FEED_ROWS + 1);
    }

    /**
     * The export links on the runtime list page ({@code downloadExport}) only put
     * the filter inputs in the query string — never {@code _offset}/{@code _limit},
     * because an export has no paging UI. With nothing to strip, {@code listData}
     * used to fall back to the list's own {@code page_size}, so a 5000-row list
     * exported to a file holding the grid's first page and said nothing about it.
     * The export default therefore has to be the feed ceiling, not the page size.
     */
    @Test
    void csvExportIsNotTruncatedToTheListPageSize() throws Exception {
        Fixture f = seed(5, 12);

        MvcResult result = mockMvc.perform(get(exportUrl(f, "csv"))
                        .sessionAttr("nexabuilder.user", adminSessionUser()))
                .andExpect(status().isOk())
                .andReturn();

        String body = result.getResponse().getContentAsString(StandardCharsets.UTF_8);
        String[] lines = body.substring(BOM.length()).split("\r\n");
        // 1 header + all 12 rows, not the 5 the grid would page to.
        assertThat(lines).hasSize(13);
    }

    /**
     * Same list, same absence of {@code _limit} — asserted through the XLSX writer
     * to observe that all three exporters share one {@code readQueryParams}, i.e.
     * the default is injected in the single place the row readers agree on rather
     * than per endpoint.
     */
    @Test
    void xlsxExportIsNotTruncatedToTheListPageSize() throws Exception {
        Fixture f = seed(5, 12);

        MvcResult result = mockMvc.perform(get(exportUrl(f, "xlsx"))
                        .sessionAttr("nexabuilder.user", adminSessionUser()))
                .andExpect(status().isOk())
                .andReturn();

        byte[] bytes = result.getResponse().getContentAsByteArray();
        try (XSSFWorkbook wb = new XSSFWorkbook(new ByteArrayInputStream(bytes))) {
            Sheet sheet = wb.getSheetAt(0);
            // Row 0 is the header, so the last data row is index 12.
            assertThat(sheet.getLastRowNum()).isEqualTo(12);
        }
    }

    /**
     * The default must not overwrite an explicit request: a bookmarked URL that
     * asks for {@code ?_limit=3} still gets three rows.
     */
    @Test
    void explicitQueryStringLimitWinsOverTheExportDefault() throws Exception {
        Fixture f = seed(5, 12);

        MvcResult result = mockMvc.perform(get(exportUrl(f, "csv"))
                        .param("_limit", "3")
                        .sessionAttr("nexabuilder.user", adminSessionUser()))
                .andExpect(status().isOk())
                .andReturn();

        String body = result.getResponse().getContentAsString(StandardCharsets.UTF_8);
        String[] lines = body.substring(BOM.length()).split("\r\n");
        assertThat(lines).hasSize(4);
    }

    @Test
    void missingSessionUserIs403ForAllFormats() throws Exception {
        Fixture f = seed();

        for (String format : FORMATS) {
            // No "nexabuilder.user" session attribute → canView(null, …) is
            // false → AccessDeniedException → AccessAuditHandler's /api/ branch.
            mockMvc.perform(get(exportUrl(f, format)))
                    .andExpect(status().isForbidden())
                    .andExpect(content().contentType("application/json;charset=UTF-8"))
                    .andExpect(jsonPath("$.success", is(false)))
                    .andExpect(jsonPath("$.message", is("Access denied")));
        }
    }
}
package com.nexabuilder.api.controller;

