/**
 * Streamed CSV / XLSX / PDF export for any list definition.
 *
 * <p>Same data and filter contract as {@code POST /api/v1/builder/lists/{listId}/data}
 * — except the rows come back as a downloadable file. Filter values are read
 * from the query string so the export URL can be a plain {@code <a href>}
 * (no JS body, no CSRF dance, easy to bookmark for ad-hoc reporting).</p>
 *
 * <p>Endpoints
 * <ul>
 *   <li>{@code GET /api/v1/lists/{listId}/export.csv} — UTF-8 CSV with a BOM
 *       so Excel-Korean opens it without garbling Hangul.</li>
 *   <li>{@code GET /api/v1/lists/{listId}/export.xlsx} — single-sheet
 *       workbook via POI's streaming writer.</li>
 *   <li>{@code GET /api/v1/lists/{listId}/export.pdf} — landscape A4 table
 *       via OpenPDF.</li>
 * </ul>
 *
 * <p>Access control reuses {@link ScreenPermissionService} — if the same user
 * can view the list at {@code /app/list/{listId}}, they can also export it.
 * Lists in the trash ({@code deleted_at} set) are "not found" here just as
 * they are on the runtime page (400 JSON via the global handler, no file bytes).
 */
@RestController
@RequiredArgsConstructor
@Slf4j
public class ListExportController {

    private final NexaUiService uiService;
    private final ScreenPermissionService screenPermissions;
    private final ObjectMapper objectMapper;

    private static final DateTimeFormatter FMT = DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss");

    @GetMapping("/api/v1/lists/{listId}/export.csv")
    public void exportCsv(@PathVariable String listId,
                          HttpServletRequest request,
                          HttpServletResponse response,
                          HttpSession session) throws IOException {

        // 1. Resolve (rejecting trashed lists) & gate by screen permission.
        NexaListDef list = resolveExportable(listId, session);

        // 2. Resolve column order + labels from the list's columnsJson.
        //    Falls back to "every row key in the order Jackson hands them
        //    back" if the list has no explicit columns — better than
        //    silently dropping data.
        List<ColumnSpec> columns = resolveColumns(list);

        // 3. Run the same query the runtime list grid uses; query-string
        //    params are forwarded so filters apply.
        Map<String, Object> params = readQueryParams(request);
        RecordSet rs = uiService.listData(listId, params);

        // 4. Stream the response. text/csv with UTF-8 + BOM is the most
        //    portable combination — opens directly in Excel-Korean without
        //    the mojibake users get from raw UTF-8.
        response.setStatus(HttpServletResponse.SC_OK);
        response.setContentType("text/csv;charset=UTF-8");
        response.setHeader("Content-Disposition", contentDisposition(filename(list, "csv")));

        try (OutputStream os = response.getOutputStream();
             Writer w = new OutputStreamWriter(os, StandardCharsets.UTF_8)) {
            // UTF-8 BOM — Excel-Korean autodetects encoding from this.
            w.write('﻿');

            // If we couldn't pull columns from columnsJson, derive them
            // from the first row so the header row at least matches the data.
            if (columns.isEmpty() && !rs.getRows().isEmpty()) {
                for (String key : rs.getRows().get(0).keySet()) {
                    columns.add(new ColumnSpec(key, key));
                }
            }

            // Header row
            writeRow(w, columns.stream().map(c -> c.label).toList());

            // Data rows — look the value up both by exact field name and
            // by case-insensitive variants so column-config "Field" works
            // regardless of how the DB driver upper/lower-cases column
            // names in the result map.
            for (Map<String, Object> row : rs.getRows()) {
                List<String> cells = new ArrayList<>(columns.size());
                for (ColumnSpec c : columns) cells.add(stringify(lookup(row, c.field)));
                writeRow(w, cells);
            }
            w.flush();
        }
    }

    /**
     * XLSX export — same data + permission contract as the CSV path,
     * rendered into a single-sheet workbook via Apache POI's streaming
     * SXSSF writer so we don't have to load the entire result set into
     * memory. Header row repeats column labels; data cells are plain
     * strings (the runtime stores everything as text already).
     */
    @GetMapping("/api/v1/lists/{listId}/export.xlsx")
    public void exportXlsx(@PathVariable String listId,
                           HttpServletRequest request,
                           HttpServletResponse response,
                           HttpSession session) throws IOException {

        NexaListDef list = resolveExportable(listId, session);

        List<ColumnSpec> columns = resolveColumns(list);
        Map<String, Object> params = readQueryParams(request);
        RecordSet rs = uiService.listData(listId, params);

        if (columns.isEmpty() && !rs.getRows().isEmpty()) {
            for (String key : rs.getRows().get(0).keySet()) {
                columns.add(new ColumnSpec(key, key));
            }
        }

        response.setStatus(HttpServletResponse.SC_OK);
        response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
        response.setHeader("Content-Disposition", contentDisposition(filename(list, "xlsx")));

        // SXSSFWorkbook streams rows to disk in 100-row windows. For
        // typical metadata-driven lists (<10k rows) the difference vs
        // the in-memory XSSFWorkbook is negligible, but it guarantees
        // we don't OOM on a particularly large export.
        try (org.apache.poi.xssf.streaming.SXSSFWorkbook wb =
                new org.apache.poi.xssf.streaming.SXSSFWorkbook(100);
             OutputStream os = response.getOutputStream()) {
            org.apache.poi.ss.usermodel.Sheet sheet = wb.createSheet(listId);
            // Header row — bold so it stands out when opened in Excel.
            org.apache.poi.ss.usermodel.CellStyle headerStyle = wb.createCellStyle();
            org.apache.poi.ss.usermodel.Font bold = wb.createFont();
            bold.setBold(true);
            headerStyle.setFont(bold);

            org.apache.poi.ss.usermodel.Row header = sheet.createRow(0);
            for (int i = 0; i < columns.size(); i++) {
                org.apache.poi.ss.usermodel.Cell c = header.createCell(i);
                c.setCellValue(columns.get(i).label);
                c.setCellStyle(headerStyle);
            }
            int rowIdx = 1;
            for (Map<String, Object> row : rs.getRows()) {
                org.apache.poi.ss.usermodel.Row r = sheet.createRow(rowIdx++);
                for (int i = 0; i < columns.size(); i++) {
                    r.createCell(i).setCellValue(stringify(lookup(row, columns.get(i).field)));
                }
            }
            wb.write(os);
            wb.dispose();
        }
    }

    /**
     * PDF export — same data + permission contract as the CSV path,
     * rendered into a landscape A4 table using OpenPDF. Hangul renders
     * via the bundled HYSMyeongJo CJK font; falls back to Helvetica if
     * the CJK pack isn't available at runtime.
     */
    @GetMapping("/api/v1/lists/{listId}/export.pdf")
    public void exportPdf(@PathVariable String listId,
                          HttpServletRequest request,
                          HttpServletResponse response,
                          HttpSession session) throws IOException {

        NexaListDef list = resolveExportable(listId, session);

        List<ColumnSpec> columns = resolveColumns(list);
        Map<String, Object> params = readQueryParams(request);
        RecordSet rs = uiService.listData(listId, params);

        response.setStatus(HttpServletResponse.SC_OK);
        response.setContentType("application/pdf");
        response.setHeader("Content-Disposition", contentDisposition(filename(list, "pdf")));

        // Landscape A4 — most reports are wider than they are tall and
        // a wide list table looks miserable in portrait.
        Document doc = new Document(PageSize.A4.rotate(), 36, 36, 48, 36);
        try (OutputStream os = response.getOutputStream()) {
            PdfWriter.getInstance(doc, os);
            doc.open();

            // Title + subtitle. Use the list's title / listName for the
            // header so the printed sheet matches what the operator sees
            // in the runtime grid.
            Font titleFont = chooseFont(16, Font.BOLD);
            String titleText = list.getTitle() != null && !list.getTitle().isBlank()
                    ? list.getTitle() : (list.getListName() != null ? list.getListName() : list.getListId());
            doc.add(new Paragraph(titleText, titleFont));
            if (list.getDescription() != null && !list.getDescription().isBlank()) {
                doc.add(new Paragraph(list.getDescription(), chooseFont(9, Font.ITALIC)));
            }
            doc.add(new Paragraph(
                    "출력: " + LocalDateTime.now().toString() + "    행: " + rs.getRows().size(),
                    chooseFont(8, Font.NORMAL)));
            doc.add(new Paragraph(" "));  // small spacer

            if (columns.isEmpty() && !rs.getRows().isEmpty()) {
                for (String key : rs.getRows().get(0).keySet()) {
                    columns.add(new ColumnSpec(key, key));
                }
            }
            if (columns.isEmpty()) {
                doc.add(new Paragraph("표시할 데이터가 없습니다.", chooseFont(11, Font.NORMAL)));
                doc.close();
                return;
            }

            PdfPTable table = new PdfPTable(columns.size());
            table.setWidthPercentage(100);
            table.setHeaderRows(1);

            // Header row — coloured fill keeps long lists readable when
            // they spill to subsequent pages (header repeats automatically
            // because we called setHeaderRows above).
            Font headerFont = chooseFont(10, Font.BOLD);
            for (ColumnSpec c : columns) {
                PdfPCell cell = new PdfPCell(new Phrase(c.label, headerFont));
                cell.setBackgroundColor(new Color(0xE9, 0xEC, 0xEF));
                cell.setPadding(6f);
                table.addCell(cell);
            }

            // Data rows. Stringify the same way the CSV path does so the
            // two export modes stay value-identical.
            Font bodyFont = chooseFont(9, Font.NORMAL);
            for (Map<String, Object> row : rs.getRows()) {
                for (ColumnSpec c : columns) {
                    PdfPCell cell = new PdfPCell(new Phrase(stringify(lookup(row, c.field)), bodyFont));
                    cell.setPadding(4f);
                    cell.setVerticalAlignment(Element.ALIGN_TOP);
                    table.addCell(cell);
                }
            }
            doc.add(table);
            doc.close();
        } catch (org.openpdf.text.DocumentException e) {
            throw new IOException("PDF write failed", e);
        }
    }

    /**
     * Resolve a CJK-capable font, falling back to the built-in Helvetica
     * if the CJK pack isn't on the classpath. The CJK font produces real
     * glyphs for Hangul / Hanzi / Kanji; Helvetica replaces them with
     * tofu, so the export is still readable but mojibake'd.
     */
    private static Font chooseFont(int size, int style) {
        try {
            // HYSMyeongJoStd-Medium ships with OpenPDF's CJK pack.
            org.openpdf.text.pdf.BaseFont bf = org.openpdf.text.pdf.BaseFont.createFont(
                    "HYSMyeongJoStd-Medium", "UniKS-UCS2-H",
                    org.openpdf.text.pdf.BaseFont.NOT_EMBEDDED);
            return new Font(bf, size, style);
        } catch (Exception e) {
            return FontFactory.getFont(FontFactory.HELVETICA, size, style);
        }
    }

    // ---------------------------------------------------------------- helpers

    /**
     * Shared entry gate for all three formats: look the list up, refuse
     * soft-deleted ones, then check the caller's screen permission.
     *
     * <p>Soft-deleted lists (migration 027) must look "gone" here exactly
     * as they do in {@link NexaUiService#listDefinition} — otherwise a
     * bookmarked export URL keeps serving the data of a list the operator
     * has already put in the trash. The verdict lives in
     * {@link NexaUiService#requireLiveList} so the runtime page, the data
     * feed and the exporters cannot drift apart; it throws the same
     * exception type + message everywhere and
     * {@code GlobalExceptionHandler.handleIllegalArgument} turns it into
     * the same 400 JSON.
     *
     * <p>Must be called before {@code response.getOutputStream()} is opened
     * — the exporters stream, so a throw after that point would leak a
     * partial file body instead of the JSON error.
     *
     * <p>A 403 here flows through GlobalExceptionHandler →
     * AccessAuditHandler, so the attempt is audit-logged just like a
     * runtime page view.
     */
    private NexaListDef resolveExportable(String listId, HttpSession session) {
        NexaListDef list = uiService.requireLiveList(listId);
        User user = (User) session.getAttribute("nexabuilder.user");
        if (!screenPermissions.canView(user, "LIST", listId)) {
            throw new AccessDeniedException("Not permitted to export list: " + listId);
        }
        return list;
    }

    /** Map of column field → label, taken from list.columnsJson (drop hidden). */
    @SuppressWarnings("unchecked")
    private List<ColumnSpec> resolveColumns(NexaListDef list) {
        List<ColumnSpec> out = new ArrayList<>();
        String json = list.getColumnsJson();
        if (json == null || json.isBlank()) return out;
        try {
            List<Map<String, Object>> cols = objectMapper.readValue(json, List.class);
            for (Map<String, Object> col : cols) {
                Object hidden = col.get("hidden");
                if (Boolean.TRUE.equals(hidden) || "true".equals(String.valueOf(hidden))) continue;
                String field = String.valueOf(col.getOrDefault("field", col.get("name")));
                String label = String.valueOf(col.getOrDefault("label", field));
                if (field == null || "null".equals(field) || field.isBlank()) continue;
                out.add(new ColumnSpec(field, label));
            }
        } catch (Exception e) {
            log.warn("Could not parse columnsJson for list {}: {}", list.getListId(), e.getMessage());
        }
        return out;
    }

    /**
     * Servlet query params → Map<String, Object>, single values only.
     *
     * <p>An export has no paging UI, so nothing puts {@code _limit} in the query
     * string — {@code downloadExport} on the runtime list page sends the filter
     * inputs and nothing else. Without it {@code NexaUiService.listData} falls
     * back to the list's own {@code page_size} (or 100), which made every export
     * silently hold just the grid's first page. The default here is therefore the
     * feed ceiling {@link NexaUiService#MAX_FEED_ROWS}: the whole filtered result
     * up to the row cap {@code listData} enforces anyway. A caller that does
     * specify {@code _limit} is respected — we only fill the gap.
     *
     * <p>Injected in this one method, not at the three call sites: {@code
     * exportCsv} / {@code exportXlsx} / {@code exportPdf} all read their rows
     * through here, so a single default keeps the three files byte-comparable.
     * {@code _offset} is left alone — {@code listData}'s 0 default is already right.
     */
    private Map<String, Object> readQueryParams(HttpServletRequest request) {
        Map<String, Object> out = new LinkedHashMap<>();
        request.getParameterMap().forEach((k, v) -> {
            if (v != null && v.length > 0) out.put(k, v[0]);
        });
        out.putIfAbsent("_limit", NexaUiService.MAX_FEED_ROWS);
        return out;
    }

    private Object lookup(Map<String, Object> row, String field) {
        if (row.containsKey(field)) return row.get(field);
        String upper = field.toUpperCase(Locale.ROOT);
        if (row.containsKey(upper)) return row.get(upper);
        String lower = field.toLowerCase(Locale.ROOT);
        if (row.containsKey(lower)) return row.get(lower);
        return null;
    }

    /**
     * Build a display-friendly filename from the list's title (when
     * present) or fall back to the listId. Strips characters that
     * filesystems on Windows don't allow, and adds a yyyyMMdd-HHmmss
     * suffix so repeated downloads don't overwrite each other.
     */
    private String filename(NexaListDef list, String ext) {
        String base = (list.getTitle() != null && !list.getTitle().isBlank())
                ? list.getTitle()
                : (list.getListName() != null && !list.getListName().isBlank()
                        ? list.getListName() : list.getListId());
        // Reserved on Windows: <>:"/\|?* — also strip control chars.
        base = base.replaceAll("[\\\\/:*?\"<>|\\p{Cntrl}]", "_").trim();
        if (base.isEmpty()) base = list.getListId();
        return base + "_" + LocalDateTime.now().format(FMT) + "." + ext;
    }

    /**
     * Build the {@code Content-Disposition} header value with both the
     * RFC 2616 {@code filename=} (ASCII-safe fallback) and the RFC 5987
     * {@code filename*=UTF-8''…} variant carrying the Unicode form.
     * Modern browsers prefer the latter; legacy clients fall back to
     * the former. Spaces in the percent-encoded form are
     * intentionally encoded as {@code %20} (not {@code +}) per RFC 5987.
     */
    private String contentDisposition(String filename) {
        String ascii = filename.replaceAll("[^\\x20-\\x7E]", "_");
        // URLEncoder uses application/x-www-form-urlencoded rules which
        // emit "+" for spaces and don't encode "*". Fix both manually to
        // get a clean RFC 5987 value.
        String encoded = URLEncoder.encode(filename, StandardCharsets.UTF_8)
                .replace("+", "%20")
                .replace("*", "%2A")
                .replace("'", "%27")
                .replace("(", "%28")
                .replace(")", "%29");
        return "attachment; filename=\"" + ascii + "\"; filename*=UTF-8''" + encoded;
    }

    /** RFC-4180-flavoured CSV row writer — quotes only when needed. */
    private void writeRow(Writer w, List<String> cells) throws IOException {
        for (int i = 0; i < cells.size(); i++) {
            if (i > 0) w.write(',');
            w.write(escapeCsv(cells.get(i)));
        }
        w.write("\r\n");
    }

    private String escapeCsv(String value) {
        if (value == null) return "";
        boolean needsQuote = value.contains(",") || value.contains("\"")
                || value.contains("\n") || value.contains("\r");
        if (!needsQuote) return value;
        return "\"" + value.replace("\"", "\"\"") + "\"";
    }

    private String stringify(Object value) {
        if (value == null) return "";
        if (value instanceof java.sql.Timestamp ts) {
            return ts.toLocalDateTime().toString();
        }
        if (value instanceof java.sql.Date d) {
            return d.toLocalDate().toString();
        }
        return value.toString();
    }

    private record ColumnSpec(String field, String label) {}
